+import { afterEach, describe, expect, it, vi } from "vitest";
+
+const ORIG = { ...process.env };
+
+afterEach(() => {
+	process.env = { ...ORIG };
+});
+
+async function loadConfig(value?: string) {
+	if (value === undefined) {
+		delete process.env["PLATFORM_FRAMEWORK_ENABLED"];
+	} else {
+		process.env["PLATFORM_FRAMEWORK_ENABLED"] = value;
+	}
+	vi.resetModules();
+	return import("./config.js");
+}
+
+describe("PLATFORM_FRAMEWORK_ENABLED", () => {
+	it("is on by default — a deployed env talks to a real platform-framework", async () => {
+		const { PLATFORM_FRAMEWORK_ENABLED } = await loadConfig();
+		expect(PLATFORM_FRAMEWORK_ENABLED).toBe(true);
+	});
+
+	it('is off only when explicitly set to "false"', async () => {
+		// e2e runs set this so the shared repository stays fully mocked and the
+		// suite never depends on real config-var state.
+		const { PLATFORM_FRAMEWORK_ENABLED } = await loadConfig("false");
+		expect(PLATFORM_FRAMEWORK_ENABLED).toBe(false);
+	});
+
+	it("stays on for a blank or unrecognized value", async () => {
+		// A declared-but-empty env var (e.g. copied from .env.example) must not
+		// silently disable platform-framework in a deployed environment.
+		expect((await loadConfig("")).PLATFORM_FRAMEWORK_ENABLED).toBe(true);
+		expect((await loadConfig("true")).PLATFORM_FRAMEWORK_ENABLED).toBe(true);
+	});
+});

