+import { describe, expect, it } from "vitest";
+import {
+	isLegacyRoleSlug,
+	LEGACY_ROLE_SLUGS,
+	legacyRoleSlugToSystemRoleSlug,
+	pfRoleIntToLegacyRoleSlug,
+	translateLegacyRole,
+} from "./legacy-translation.js";
+
+describe("LEGACY_ROLE_SLUGS", () => {
+	it("contains exactly the four hyphenated legacy role slugs", () => {
+		expect(LEGACY_ROLE_SLUGS).toEqual([
+			"admin",
+			"staff",
+			"store-manager",
+			"store-staff",
+		]);
+	});
+});
+
+describe("isLegacyRoleSlug", () => {
+	it("accepts each legacy role slug", () => {
+		for (const slug of LEGACY_ROLE_SLUGS) {
+			expect(isLegacyRoleSlug(slug)).toBe(true);
+		}
+	});
+
+	it("rejects underscored variants", () => {
+		expect(isLegacyRoleSlug("store_manager")).toBe(false);
+		expect(isLegacyRoleSlug("store_staff")).toBe(false);
+	});
+
+	it("rejects system role slugs and unknown values", () => {
+		expect(isLegacyRoleSlug("sitoo-admin")).toBe(false);
+		expect(isLegacyRoleSlug("viewer")).toBe(false);
+		expect(isLegacyRoleSlug("")).toBe(false);
+	});
+});
+
+describe("legacyRoleSlugToSystemRoleSlug", () => {
+	it("maps each legacy role slug to its sitoo-* system role slug", () => {
+		expect(legacyRoleSlugToSystemRoleSlug("admin")).toBe("sitoo-admin");
+		expect(legacyRoleSlugToSystemRoleSlug("staff")).toBe(
+			"sitoo-head-office-user",
+		);
+		expect(legacyRoleSlugToSystemRoleSlug("store-manager")).toBe(
+			"sitoo-store-manager",
+		);
+		expect(legacyRoleSlugToSystemRoleSlug("store-staff")).toBe(
+			"sitoo-store-staff",
+		);
+	});
+
+	it("returns undefined for unknown slugs", () => {
+		expect(legacyRoleSlugToSystemRoleSlug("sitoo-admin")).toBeUndefined();
+		expect(legacyRoleSlugToSystemRoleSlug("store_manager")).toBeUndefined();
+	});
+});
+
+describe("pfRoleIntToLegacyRoleSlug", () => {
+	it("maps platform-framework role integers to legacy role slugs", () => {
+		expect(pfRoleIntToLegacyRoleSlug(10)).toBe("admin");
+		expect(pfRoleIntToLegacyRoleSlug(20)).toBe("staff");
+		expect(pfRoleIntToLegacyRoleSlug(30)).toBe("store-manager");
+		expect(pfRoleIntToLegacyRoleSlug(40)).toBe("store-staff");
+	});
+
+	it("returns undefined for viewer (50) and unknown integers", () => {
+		expect(pfRoleIntToLegacyRoleSlug(50)).toBeUndefined();
+		expect(pfRoleIntToLegacyRoleSlug(0)).toBeUndefined();
+		expect(pfRoleIntToLegacyRoleSlug(99)).toBeUndefined();
+	});
+});
+
+describe("translateLegacyRole", () => {
+	it("produces an assignment with source=legacy", () => {
+		const result = translateLegacyRole({
+			legacyRoleSlug: "admin",
+			userId: "user-1",
+			organizationId: "org-1",
+			accountId: 1,
+			siteId: 10,
+		});
+
+		expect(result.source).toBe("legacy");
+		expect(result.role_slug).toBe("admin");
+		expect(result.client).toBe("bo");
+		expect(result.site_ids).toEqual([10]);
+	});
+
+	it("store-manager maps to pos client", () => {
+		const result = translateLegacyRole({
+			legacyRoleSlug: "store-manager",
+			userId: "user-1",
+			organizationId: "org-1",
+			accountId: 1,
+			siteId: 10,
+		});
+
+		expect(result.client).toBe("pos");
+	});
+
+	it("legacy assignments are always per-site scoped", () => {
+		const result = translateLegacyRole({
+			legacyRoleSlug: "staff",
+			userId: "user-1",
+			organizationId: "org-1",
+			accountId: 1,
+			siteId: 10,
+		});
+
+		expect(result.account_ids).toEqual([1]);
+		expect(result.site_ids).toEqual([10]);
+		expect(result.store_ids).toEqual([]);
+	});
+
+	it("legacy assignment includes system role permissions", () => {
+		const result = translateLegacyRole({
+			legacyRoleSlug: "admin",
+			userId: "user-1",
+			organizationId: "org-1",
+			accountId: 1,
+			siteId: 10,
+		});
+
+		expect(
+			Object.keys(result.permissions.bo).length +
+				Object.keys(result.permissions.pos).length,
+		).toBeGreaterThan(0);
+		// Admin should include common admin perms
+		expect(result.permissions.bo).toHaveProperty("users.read");
+		expect(result.permissions.bo).toHaveProperty("users.write");
+	});
+
+	it("store-staff has pos client and legacy source", () => {
+		const result = translateLegacyRole({
+			legacyRoleSlug: "store-staff",
+			userId: "user-1",
+			organizationId: "org-1",
+			accountId: 1,
+			siteId: 10,
+		});
+
+		expect(result.client).toBe("pos");
+		expect(result.source).toBe("legacy");
+		expect(result.role_slug).toBe("store-staff");
+	});
+
+	it("emits the legacy role slug itself, not the system role slug", () => {
+		const result = translateLegacyRole({
+			legacyRoleSlug: "staff",
+			userId: "user-1",
+			organizationId: "org-1",
+			accountId: 1,
+			siteId: 10,
+		});
+
+		expect(result.role_slug).toBe("staff");
+		expect(result.role_slug).not.toBe("sitoo-head-office-user");
+	});
+});

