+// services/iam-api/src/repositories/platform-framework/forwarding.ts
+import { extractAuthStrategy } from "../../shared/auth-header.js";
+import type { PlatformCallContext } from "./types.js";
+
+/**
+ * Whether a caller's `Authorization` header can be forwarded to
+ * platform-framework. PF's `/v2` API accepts **HTTP Basic only**, so a Bearer
+ * token (an Auth0 caller, or a local dev/e2e ephemeral token) is not a usable
+ * credential there — forwarding it would just earn a 401. Call sites that need
+ * a real PF read use this to decide up front, instead of discovering it as an
+ * upstream auth failure.
+ */
+export function isForwardablePlatformCredential(
+	authorization: string | undefined,
+): authorization is string {
+	return extractAuthStrategy(authorization) === "basic";
+}
+
+/**
+ * Derives the context for a real platform-framework call from a caller's auth
+ * context, or `undefined` when the caller cannot make one. Both preconditions
+ * live here so every call site agrees on them: a `nodeId` to route the host,
+ * and a forwardable (Basic) credential to authenticate with. Call sites branch
+ * on presence of the whole context rather than re-checking the parts.
+ */
+export function platformCallContextFromAuth(auth: {
+	nodeId?: number;
+	authorization?: string;
+}): PlatformCallContext | undefined {
+	return auth.nodeId != null &&
+		isForwardablePlatformCredential(auth.authorization)
+		? { nodeId: auth.nodeId, authorization: auth.authorization }
+		: undefined;
+}

