+import { afterEach, describe, expect, it, vi } from "vitest";
+import type { PlatformFrameworkRepository } from "./types.js";
+
+// Distinct sentinel fns per method so we can assert, by reference identity,
+// which implementation (mock vs real) each composed method resolves to.
+function sentinelRepo(): PlatformFrameworkRepository {
+	return {
+		isRolesV2EnabledForOrg: vi.fn(),
+		isRolesV2EnabledForAccount: vi.fn(),
+		getConfigVars: vi.fn(),
+		getLegacyUserRoles: vi.fn(),
+		getSiteConfig: vi.fn(),
+		getSitesForAccount: vi.fn(),
+		userExistsInSite: vi.fn(),
+	} as unknown as PlatformFrameworkRepository;
+}
+
+const mockImpl = sentinelRepo();
+const realImpl = sentinelRepo();
+
+async function loadRepository(enabled: boolean) {
+	vi.resetModules();
+	vi.doMock("../../config.js", () => ({
+		PLATFORM_FRAMEWORK_ENABLED: enabled,
+		PLATFORM_FRAMEWORK_BASE_URL: "",
+	}));
+	vi.doMock("./mock.js", () => ({
+		createMockPlatformFramework: () => mockImpl,
+	}));
+	vi.doMock("./real.js", () => ({
+		createRealPlatformFramework: () => realImpl,
+	}));
+	const mod = await import("./singleton.js");
+	return mod.platformRepository;
+}
+
+afterEach(() => {
+	vi.resetModules();
+	vi.clearAllMocks();
+});
+
+describe("platformRepository composition", () => {
+	// The reads carry no credential of their own — they authenticate as the
+	// caller (PlatformCallContext.authorization). What gates them is an explicit
+	// opt-in, so an env that has not enabled platform-framework stays fully
+	// mocked and never depends on a real config-var value.
+	it("routes every data-read method to the real client when enabled", async () => {
+		const repo = await loadRepository(true);
+		expect(repo.isRolesV2EnabledForAccount).toBe(
+			realImpl.isRolesV2EnabledForAccount,
+		);
+		expect(repo.getConfigVars).toBe(realImpl.getConfigVars);
+		expect(repo.getLegacyUserRoles).toBe(realImpl.getLegacyUserRoles);
+		expect(repo.getSiteConfig).toBe(realImpl.getSiteConfig);
+		expect(repo.getSitesForAccount).toBe(realImpl.getSitesForAccount);
+	});
+
+	it("keeps userExistsInSite and org-level rolesv2 on the mock", async () => {
+		// org-level: platform-framework has no org-scoped config endpoint, so the
+		// real implementation throws — the mock keeps that path permissive.
+		// userExistsInSite: still deliberately mocked (ticket 04), even though the
+		// real one already authenticates as the caller.
+		const repo = await loadRepository(true);
+		expect(repo.userExistsInSite).toBe(mockImpl.userExistsInSite);
+		expect(repo.isRolesV2EnabledForOrg).toBe(mockImpl.isRolesV2EnabledForOrg);
+	});
+
+	it("uses the full mock when platform-framework is not enabled", async () => {
+		// Ephemeral, local dev and e2e leave PLATFORM_FRAMEWORK_ENABLED unset:
+		// rolesv2 then resolves permissively from the mock instead of depending on
+		// a real config-var those accounts do not have.
+		const repo = await loadRepository(false);
+		expect(repo.isRolesV2EnabledForAccount).toBe(
+			mockImpl.isRolesV2EnabledForAccount,
+		);
+		expect(repo.getConfigVars).toBe(mockImpl.getConfigVars);
+		expect(repo.getLegacyUserRoles).toBe(mockImpl.getLegacyUserRoles);
+		expect(repo.getSiteConfig).toBe(mockImpl.getSiteConfig);
+		expect(repo.getSitesForAccount).toBe(mockImpl.getSitesForAccount);
+		expect(repo.userExistsInSite).toBe(mockImpl.userExistsInSite);
+		expect(repo.isRolesV2EnabledForOrg).toBe(mockImpl.isRolesV2EnabledForOrg);
+	});
