+// services/iam-api/src/shared/auth-header.ts
+
+export type AuthStrategy = "jwt" | "basic";
+
+export const BEARER_PREFIX = "Bearer ";
+export const BASIC_PREFIX = "Basic ";
+
+/**
+ * Classifies an `Authorization` header by scheme. Single definition of what
+ * counts as Basic vs Bearer — inbound auth (middleware/auth.ts) and outbound
+ * forwarding to platform-framework (repositories/platform-framework) must agree
+ * on it, or a header accepted as Basic on the way in could be judged
+ * non-forwardable on the way out.
+ */
+export function extractAuthStrategy(
+	header: string | undefined,
+): AuthStrategy | null {
+	if (!header) {
+		return null;
+	}
+	if (header.startsWith(BEARER_PREFIX)) {
+		return "jwt";
+	}
+	if (header.startsWith(BASIC_PREFIX)) {
+		return "basic";
+	}
+	return null;
+}

